import {render} from 'preact';
import {useState} from 'preact/hooks';
import {NARROW_MEDIA,PANEL_MEDIA,useMedia} from '../../app/src/shell/narrow';
import {Rail} from '../../app/src/shell/Rail';
import {AppFrame} from '../../app/src/shell/AppFrame';
import {SidePanel} from '../../app/src/ds/SidePanel';
import {CommandTrigger} from '../../app/src/shell/CommandTrigger';
import snapshot from './ui/snapshot.json';
import {TopBar} from '../../app/src/shell/TopBar';
import {Workspace} from '../../app/src/screens/workspace/Workspace';
import {TaskContext} from '../../app/src/screens/task-shared';
import {FrameContext} from '../../app/src/shell/slots';
import {initialState} from '../../app/src/data/store';
import fixture from './ui/task-get.json';
const mode=new URLSearchParams(location.search).get('mode');
const fullHeader=new URLSearchParams(location.search).has('header');
const paramsLog:any[]=[];(window as any).workspaceParams=paramsLog;
const calls:string[]=[];(window as any).workspaceCalls=calls;
const task={...fixture,id:'workspace-task',title:'Inspect workspace session',goal:'Inspect workspace session',state:'running',executor:'codex',updatedAt:Date.now()/1000,progress:{phase:'working'},review:null,reviewRequest:null,worktree:'/tmp/disposable-worktree'};
if(mode==='counts')task.attempts=[{executor:'codex',startedAt:Date.now()/1000-60,endedAt:Date.now()/1000-30,log:''},{executor:'codex',startedAt:Date.now()/1000-20,log:''}] as any;
const info={host:'builtin',live:true,driving:mode==='driving',takeover:{available:mode==='starting'},attempt:1,cols:80,rows:24,controller:null,viewers:0,capabilities:{control:true,resize:true},attach:{ws:'/session'}};
const tasks=Array.from({length:mode==='counts'?20:1},(_,i)=>({...task,id:i?`workspace-task-${i}`:task.id,title:i?`Workspace task ${i}`:task.title}));
if(mode==='childfile'){tasks[0]={...tasks[0]!,executor:null} as any;tasks.push({...task,id:'workspace-child',title:'Child session'});}
const state={...initialState(),connected:true,snapshot:{tasks,attention:[],repos:[]},features:{...initialState().features,ops:new Set(['task.get','task.session','terminal.list','dispatch.list'])}} as any;
const api={call:async(op:string,params:any)=>{calls.push(op);paramsLog.push({op,params});if(op==='task.get')return {...task,...tasks.find(t=>t.id===params.id)};if(op==='task.list')return {tasks};if(op==='dispatch.list')return {tasks:mode==='childfile'?tasks.map((t,n)=>({id:t.id,parentId:n?task.id:null,rootId:task.id,depth:n,title:t.title,state:t.state,executor:t.executor,rev:1})):[]};if(op==='dispatch.tree')return {nodes:[],totals:{}};if(op==='terminal.list')return [{id:'shell-fixture',cwd:task.worktree,title:'Fixture',live:true,cols:80,rows:24,attach:{ws:'/shell'}}];if(op==='task.session')return info;if(op==='session.file.read')return {path:'src/a.ts',kind:'code',text:'export const a = 1;',size:19,modified:'2026-10-30',line:2};if(op==='task.log')return {stdout:'Latest output',stderr:''};if(op==='task.takeover')throw Error('Duplicate takeover');return {};}} as any;
function App(){const [revision,setRevision]=useState(0);(window as any).workspaceFinish=()=>{tasks[0]={...tasks[0]!,state:'done',rev:(tasks[0]!.rev??0)+1};setRevision(n=>n+1);};(window as any).workspaceTick=(changed=false)=>{if(changed)tasks[0]={...tasks[0]!,rev:(tasks[0]!.rev??0)+1};setRevision(n=>n+1);};const [title,setTitle]=useState<HTMLElement|null>(null),[actions,setActions]=useState<HTMLElement|null>(null),[left,setLeft]=useState<HTMLElement|null>(null),[right,setRight]=useState<HTMLElement|null>(null);return <TaskContext.Provider value={{state:{...state,snapshot:{...state.snapshot,seq:revision}},api}}><FrameContext.Provider value={{title,actions,left,right,inline:false,heading(){}}}><TopBar title="Workspace" planner={null} mode="normal" connected lastUpdate={null} onDelegate={()=>{}} context={setTitle} actions={setActions} search={<span>Search fixture</span>}/><aside ref={setLeft}/><Workspace id={task.id} query={{repo:null,scope:null}}/><aside ref={setRight}/></FrameContext.Provider></TaskContext.Provider>;}
function FullHeaderApp(){const narrow=useMedia(NARROW_MEDIA),panels=useMedia(PANEL_MEDIA)&&!narrow;const [revision,setRevision]=useState(0);(window as any).workspaceFinish=()=>{tasks[0]={...tasks[0]!,state:'done',rev:(tasks[0]!.rev??0)+1};setRevision(n=>n+1);};(window as any).workspaceTick=(changed=false)=>{if(changed)tasks[0]={...tasks[0]!,rev:(tasks[0]!.rev??0)+1};setRevision(n=>n+1);};const [title,setTitle]=useState<HTMLElement|null>(null),[actions,setActions]=useState<HTMLElement|null>(null),[left,setLeft]=useState<HTMLElement|null>(null),[right,setRight]=useState<HTMLElement|null>(null);return <TaskContext.Provider value={{state:{...state,snapshot:{...state.snapshot,seq:revision}},api}}><FrameContext.Provider value={{title,actions,left,right,inline:!panels,heading(){}}}><AppFrame narrow={narrow} activity={<Rail narrow={narrow} route={{name:"terminal",query:{repo:null,scope:null}} as any} counts={null}/>} top={<TopBar narrow={narrow} title="Workspace" planner={fullHeader?snapshot.planner as any:null} mode="normal" connected lastUpdate={null} onDelegate={()=>{}} context={setTitle} actions={setActions} search={fullHeader?<CommandTrigger onOpen={()=>{}}/>:<span>Search fixture</span>} narrowSearch={fullHeader?<CommandTrigger narrow onOpen={()=>{}}/>:<button aria-label="Search">Search</button>}/>} left={panels&&<SidePanel side="left" label="Workspace" open onToggle={()=>{}} bar={false} resize={{key:'fixture-left',initial:272,min:200,max:480}}><div ref={setLeft}/></SidePanel>} right={panels&&<SidePanel side="right" label="Task" open onToggle={()=>{}} bar={false} resize={{key:'fixture-right',initial:320,min:260,max:560}}><div ref={setRight}/></SidePanel>} status={<footer className="pc-statusbar">Fixture status</footer>} overlay={<span className="pc-aurora-launcher"/>} mainClass="pc-main pc-main--canvas pc-main--workbench" main={<Workspace id={task.id} query={{repo:null,scope:null}}/>}/></FrameContext.Provider></TaskContext.Provider>;}
render(fullHeader?<FullHeaderApp/>:<App/>,document.getElementById('app')!);
